"""Render static and generated-history tables from exact saved exports."""
from pathlib import Path
import csv,json,math
from build_main_results import number,row
ROOT=Path(__file__).resolve().parents[1]
def read(p):return list(csv.DictReader((ROOT/p).open(encoding='utf-8-sig',newline='')))
def write(p,lines):(ROOT/'sections'/p).write_text('\n'.join(lines)+'\n',encoding='utf-8')

def interval(bounds):
    # Split the endpoints instead of rounding small bounds to signed zero.
    lo=number(bounds['lower']).strip('$');hi=number(bounds['upper']).strip('$')
    return r'\shortstack[l]{$['+lo+r',$\\$'+hi+r']$}'

def main():
    old=[r for r in read('data/full_results/attribution_decomposition.csv') if all(r[k]==v for k,v in dict(model='qwen3-8b-thinking',protocol='independent',visibility='signal_visible',relation='agree').items())]
    phi=read('data/review_supplement/phi_static.csv')
    lines=[r'% Generated by scripts/build_review_tables.py.',r'\begin{table*}[t]',r'\centering',r'{\small\setlength{\tabcolsep}{4pt}',r'\begin{tabular*}{\textwidth}{@{\extracolsep{\fill}}llrrrrrr@{}}',r'\toprule',r'\shortstack[l]{Reminder /\\instruction} & Representation & Pairs & $e_{\mathrm{self}}$ & $e_{\mathrm{other}}$ & $\Delta_{\mathrm{attr}}$ & \shortstack{Self\\MAE} & \shortstack{Other\\MAE} \\']
    for name,rows in [('Qwen3-8B',old),('Phi-4',phi)]:
        lines += [r'\midrule',r'\multicolumn{8}{l}{\textbf{'+name+r': independent agreeing readings, $S$ visible}} \\',r'\midrule']
        for r in sorted(rows,key=lambda r:(r['reminder'],r.get('output_instruction',r.get('wording')),r.get('template_id',r.get('representation')))):
            if name=='Qwen3-8B':
                vals=[float(r['metrics.'+k+'.estimate']) for k in ('self_directional_error','other_directional_error','attribution_gap','self_mae','other_mae')]
                fields=[r['reminder'].capitalize()+' / '+r['output_instruction'],r['template_id'].split('_')[0].capitalize(),r['complete_pairs']+'/'+r['candidate_pairs']]
            else:
                vals=[float(r[k]) for k in ('self_error','other_error','gap','self_mae','other_mae')]
                fields=[r['reminder'].capitalize()+' / '+r['wording'],r['representation'].capitalize(),r['complete']+'/'+r['planned']]
            assert math.isclose(vals[0]-vals[1],vals[2],abs_tol=1e-12)
            lines.append(row(fields+list(map(number,vals))))
    lines += [r'\bottomrule',r'\end{tabular*}',r'}',r'\caption{Static attribution and posterior accuracy on the same complete pairs. Qwen3 and Phi-4 use their recorded native interfaces. Bounds and exact exports are in Appendix~\ref{app:review-static}.}',r'\label{tab:main-results}',r'\end{table*}']
    write('main_results_generated.tex',lines)
    docs=json.loads((ROOT/'data/review_supplement/summaries.json').read_text())
    selections=[('Qwen3','all','All valid'),('Qwen3','visible_prefix','Visible explanation'),('Qwen3','large_error','Large error'),('Qwen3','wrong_choice','Incorrect choice'),('Qwen3','overconfident','Overconfident'),('Phi-4','all','All valid')]
    lines=[r'% Generated by scripts/build_review_tables.py.',r'\begin{table*}[t]',r'\centering',r'{\small\setlength{\tabcolsep}{4pt}',r'\begin{tabular*}{\textwidth}{@{\extracolsep{\fill}}llrrrrrr@{}}',r'\toprule',r'Model / cohort & Parents & \shortstack{Valid\\followups} & \shortstack{Parent\\MAE} & \shortstack{Copy\\pairs} & \shortstack{Copy\\mean $|R_B|$} & \shortstack{Independent\\pairs} & \shortstack{Independent\\mean $|R_B|$} \\',r'\midrule']
    for model,cohort,label in selections:
        d=docs['qwen_history' if model=='Qwen3' else 'phi_history'];c=next(x for x in d['cohorts'] if x['cohort']==cohort)
        vals=[model+' / '+label,str(c['n_parents']),str(sum(z['n_valid'] for z in c['arms']))+'/'+str(c['n_planned_children']),number(c['parent_mae']['estimate'])]
        for kind in ('copy','independent'):
            x=next(z for z in c['individual_update_errors'] if z['history_arm']=='native_self' and z['evidence_kind']==kind)
            vals += [str(x['absolute']['n_observations'])+'/'+str(x['planned_pairs']),number(x['absolute']['estimate'])]
        lines.append(row(vals))
    lines += [r'\bottomrule',r'\end{tabular*}',r'}',r'\caption{Generated histories and itemwise update error in native conversation. Qwen3 cohorts overlap. Absolute residuals use complete update pairs with equal weights over represented families.}',r'\label{tab:review-history}',r'\end{table*}']
    write('review_history_generated.tex',lines)
    # Complete wording matrix, including posterior direction and missingness.
    lines=[r'\begin{table*}[t]',r'\centering',r'{\small\setlength{\tabcolsep}{3pt}',r'\begin{tabular*}{\textwidth}{@{\extracolsep{\fill}}llrrrrl@{}}',r'\toprule',r'\shortstack[l]{Reminder /\\instruction} & Version & Complete & $e_{\mathrm{self}}$ & $e_{\mathrm{other}}$ & $\Delta_{\mathrm{attr}}$ & Gap bounds \\',r'\midrule']
    labels={'original':'Original','authorship':'Author label','dependence':'Evidence rule','author_independence':'Label independence'}
    for c in docs['four_wordings']['strata']:
        if 'template_id' in c['stratum']:continue
        s=c['stratum']
        for v,z in c['versions'].items():
            g=z['gap'];bd=g['bounds']
            lines.append(row([s['reminder'].capitalize()+' / '+s['output_instruction'],labels[v],str(c['complete_twelve_sets'])+'/'+str(c['planned_sets']),number(z['self_error']['point']['estimate']),number(z['other_error']['point']['estimate']),number(g['point']['estimate']),interval(bd)]))
        lines.append(r'\addlinespace')
    lines += [r'\bottomrule',r'\end{tabular*}',r'}',r'\caption{Four wordings on common complete sets of twelve reports. Each version retains the same numerical world and author labels. Bounds cover all planned settings.}',r'\label{tab:review-wordings}',r'\end{table*}']
    write('review_wordings_generated.tex',lines)
    lines=[r'\begin{table*}[t]',r'\centering',r'\begin{tabular*}{\textwidth}{@{\extracolsep{\fill}}llrrl@{}}',r'\toprule',r'Checkpoint / runtime & Group & Valid/planned & Family MAE & Pass \\',r'\midrule']
    for key,label in [('phi_gate','Standard Phi-4 / SDPA'),('qwen_runtime_qualification','Qwen3 / vLLM')]:
        for g in docs[key]['groups']:
            lines.append(row([label,g['group'].capitalize(),str(g['n_valid'])+'/'+str(g['n_planned']),number(g['mae']['estimate']),'Yes' if g['passes'] else 'No']))
    lines += [r'\bottomrule',r'\end{tabular*}',r'\caption{Completed numerical qualification. Standard Phi-4 qualifies before its downstream stages. The new Qwen3 runtime check is a subsequent diagnostic.}',r'\label{tab:review-qualification}',r'\end{table*}']
    write('review_qualification_generated.tex',lines)
    lines=[r'\begin{table*}[t]',r'\centering',r'{\small\setlength{\tabcolsep}{4pt}\begin{tabular*}{\textwidth}{@{\extracolsep{\fill}}llrlll@{}}',r'\toprule',r'\shortstack[l]{Reminder /\\instruction} & Form & Pairs & Self error bounds & Other error bounds & Gap bounds \\',r'\midrule']
    for z in docs['phi_static']['attribution']:
        s=z['stratum']
        if s.get('protocol')!='independent' or s.get('visibility')!='signal_visible' or s.get('relation')!='agree' or 'template_id' not in s:continue
        fields=[s['reminder'].capitalize()+' / '+s['output_instruction'],s['template_id'].split('_')[0].capitalize(),str(z['gap']['complete_valid_sets'])+'/'+str(z['gap']['candidate_sets'])]
        for k in ('self_directional_error','other_directional_error','gap'):
            bd=z[k]['bounds'];fields.append(interval(bd))
        lines.append(row(fields))
    lines += [r'\bottomrule',r'\end{tabular*}}',r'\caption{Standard Phi-4 full design bounds for independent agreeing readings. Point estimates on complete pairs appear in Table~\ref{tab:main-results}.}',r'\label{tab:review-static-bounds}',r'\end{table*}']
    write('review_static_bounds_generated.tex',lines)
    lines=[r'\begin{table*}[t]',r'\centering',r'{\small\setlength{\tabcolsep}{4pt}',r'\begin{tabular*}{\textwidth}{@{\extracolsep{\fill}}lllr rrl@{}}',r'\toprule',r'Model & Presentation & Evidence & Pairs & Signed $R_B$ & Mean $|R_B|$ & Signed residual bounds \\',r'\midrule']
    for model,key in [('Qwen3','qwen_history'),('Phi-4','phi_history')]:
        c=next(x for x in docs[key]['cohorts'] if x['cohort']=='all')
        for arm,label in [('native_self','Native history'),('replay_self','Self replay'),('replay_other','Other replay'),('replay_neutral','Neutral replay')]:
            for kind in ('copy','independent'):
                x=next(z for z in c['individual_update_errors'] if z['history_arm']==arm and z['evidence_kind']==kind)
                info=next(z for z in c['analysis']['information'] if z['stratum']==dict(evidence_kind=kind,history_arm=arm))['update']
                assert math.isclose(x['signed']['estimate'],info['residual']['estimate'],abs_tol=1e-12)
                bd=info['residual_bounds']
                lines.append(row([model,label,kind.capitalize(),str(x['absolute']['n_observations'])+'/'+str(x['planned_pairs']),number(x['signed']['estimate']),number(x['absolute']['estimate']),interval(bd)]))
    lines += [r'\bottomrule',r'\end{tabular*}',r'}',r'\caption{Signed and absolute generated history update errors on identical complete pairs. Bounds cover all constructed pairs for each signed residual.}',r'\label{tab:review-update-errors}',r'\end{table*}']
    write('review_update_errors_generated.tex',lines)
    print('Rendered 16 static rows, six history cohorts, and 16 wording rows.')

if __name__=='__main__':main()
